      if (now() - T.first > 120000) { T.n = 0; T.first = now(); }
      if (++T.n > 3) { T.until = now() + 600000; T.n = 0; rkSay('rmfail' + h.id, `buffs: the server keeps ${h.name} (cancel refused) — trying again in 10 min`, 600000); return; }
