const leadMode = () => !!(CONFIG.lead && CONFIG.lead.on);
const zoneScale = () => (leadMode() && CONFIG.lead.zoneScale) || 1;

// ---------------------------------------------------------------------------
// PRIORITIES (user 2026-10-04: "make a priority list; functions and loops must be interruptible when something more important comes")
// Lower number = more important. Whoever holds "control" owns the character/team; a MORE important task takes control from a less
// important one, which notices (interrupted(gen)) in its loops and steps aside. Less important tasks wait until control is free.
// ---------------------------------------------------------------------------
const PRIO = { SURVIVE: 0, UNFREEZE: 1, TEAM_SAFETY: 2, PORT_SAFETY: 3, ORDER: 4, LEVEL: 5, UPKEEP: 6 };
const PRIO_LIST = [
  [PRIO.SURVIVE,     'Survive: heal / potion / run away when alone / respawn'],
  [PRIO.UNFREEZE,    'Get unfrozen / unstuck: Appearing packet, click free, last resort .town'],
  [PRIO.TEAM_SAFETY, 'Team safety: help teammates under attack, res the dead, regroup anyone left behind (Giran)'],
  [PRIO.PORT_SAFETY, 'Safe teleport: fight off monsters, safe spot, everyone together and out of combat'],
  [PRIO.ORDER,       'Orders from the user/leader: !stop, !supply, !collect, !level, missions, raid hunt'],
  [PRIO.LEVEL,       'Leveling: pick spot, travel together, hunt'],
  [PRIO.UPKEEP,      'Upkeep: rebuff, class change, selling'],
];
const control = { owner: null, level: 99, gen: 0, since: 0 };
/** Take control for a task. Refused (false) while a MORE important task holds it. Returns the control generation. */
// USERORDER-2026-10-12: the user's own order (quest / any order) - nothing but survival (P0) and unfreeze (P1) may take the character
const userOrder = { name: null, since: 0 };
function userOrderSet(name) { userOrder.name = name; userOrder.since = now(); }
function userOrderEnd(name) { if (!name || userOrder.name === name) { userOrder.name = null; userOrder.since = now(); } }
/** the user order takes control now: a background task at P2+ is pushed aside (its loops see interrupted(gen) and step aside) */
function userOrderGrab(name) {
  if (control.owner && control.owner !== name && control.level < PRIO.TEAM_SAFETY) return false;   // survival / unfreeze first
  if (control.owner !== name) { if (control.owner) note(`priority: your order "${name}" takes over from "${control.owner}" (P${control.level})`); control.gen++; try { pairsTravelStop(name); } catch (e) { } }
  Object.assign(control, { owner: name, level: PRIO.ORDER, since: now() }); userOrderSet(name); return control.gen;
}
function takeControl(name, level) {
  if (userOrder.name && name !== userOrder.name && level >= PRIO.TEAM_SAFETY && control.owner === userOrder.name) return false;   // USERORDER
  if (control.owner && control.owner !== name && control.level < level) return false;
  if (control.owner !== name) {
    if (control.owner) note(`priority: "${name}" (P${level}) interrupts "${control.owner}" (P${control.level})`);
    control.gen++;
    // PAIRSGATE (2026-10-09 17:55): any order / regroup / rescue / escape above leveling ends the hunting pairs at once
    if (level < PRIO.LEVEL && name !== 'leveling') { try { pairsTravelStop(name); } catch (e) { } }
  }
  Object.assign(control, { owner: name, level, since: now() });
  return control.gen;
}
// ORDERQ (2026-10-13): its user order ends even when another task held control at that moment (the 11:08 "!town giran" still blocked !dawn at 12:09)
function releaseControl(name) { if (control.owner === name) Object.assign(control, { owner: null, level: 99, since: now() }); userOrderEnd(name); }
/** true when someone took control after 'gen' was read (the caller must step aside). */
function interrupted(gen) { return gen !== undefined && gen !== null && gen !== control.gen; }
/** A more important task than 'level' holds control right now. */
function outranked(level) { return !!control.owner && control.level < level; }
// USER RULES 2026-10-07 (after Soul Scavenger wiped team 3 at Ruins of Agony): "teams that are hunting shall not attack raid bosses — only raid
// hunt attacks raid bosses", and "raid hunt shall NOT attack any epic raid boss" (they need several teams). A raid boss / epic counts as an
// ignored mob (no self-defence, no help, no hunt target, L2Swarm's own target cancelled) unless we are in a raid on exactly that boss.
const EPIC_BOSS_RE = /^(Queen Ant|Core|Orfen|Zaken|Baium|Antharas|Valakas|Frintezza|Scarlet van Halisha|Beleth|Freya|Ice Queen Freya|Sailren|Baylor|Lilith|Anakim|Tiat|Ekimus|Istina|Octavis|Earth Wyrm Trasken)$/i;
let raidBossNameSet = null;
function isRaidBossName(name) {
  name = String(name || '').trim();
  if (!name) return false;
  if (EPIC_BOSS_RE.test(name)) return true;
  if (!raidBossNameSet) { raidBossNameSet = {}; try { raidDb().forEach(b => { raidBossNameSet[String(b.name).toLowerCase()] = true; }); } catch (e) { } }
  return !!raidBossNameSet[name.toLowerCase()];
}
// RAID BOSS BY NAME + LEVEL (user screenshot 2026-10-07 23:40): L2Toggle has ORDINARY monsters with a raid boss's name — 8x "Cat's Eye
// Bandit" titled "LvL: 15" at Abandoned Camp, while the raid boss Cat's Eye Bandit (25079) is level 30 at 53712,102656. By name alone they
// counted as the raid boss (never fought, team fled, raid "seen alive"). A creature is the raid boss only when the name matches AND its
// level (L2Swarm Level, else the title "LvL: N") is within +-3 of raidbosses_h5.json, or — level unknown — it stands within 8000 of the spawn.
function mobLvl(m) {
  let l = 0; try { l = num(m && m.Level); } catch (e) { }
  if (l > 0) return l;
  let t = ''; try { t = String((m && m.Title) || ''); } catch (e) { }
  const r = /LvL:\s*(\d+)/i.exec(t); return r ? num(r[1]) : 0;
}
let raidBossByName = null;
function raidBossEntries(name) {
  if (!raidBossByName) { raidBossByName = {}; try { raidDb().forEach(b => { const k = String(b.name).toLowerCase(); (raidBossByName[k] = raidBossByName[k] || []).push(b); }); } catch (e) { } }
  return raidBossByName[String(name || '').trim().toLowerCase()] || null;
}
function isRaidBossMob(m) {
  if (!m) return false;
  const name = String(m.Name || '').trim(); if (!name) return false;
  const list = raidBossEntries(name), lv = mobLvl(m);
  if (!list) return EPIC_BOSS_RE.test(name) && !(lv > 0 && lv < 38);     // epics not in the raid list: name, unless clearly a low monster
  let x = NaN, y = NaN; try { x = Number(m.X); y = Number(m.Y); } catch (e) { }
  return list.some(b => {
    const bl = num(b.level);
    if (lv > 0 && bl > 0) return Math.abs(lv - bl) <= 3;
    if (!isFinite(Number(b.x)) || !isFinite(x) || (!x && !y)) return true;
    return Math.hypot(Number(b.x) - x, Number(b.y) - y) <= 8000;
  });
}
// the boss of a raid MISSION counts as allowed from the moment the mission starts (2026-10-07 06:03: party 1 on its way to Chertuba of Great Soul
// fled from it because the approach runs in 'mission' mode, before raid mode sets state.bossName)
const missionBoss = { name: '', until: 0 };
App.on('swarm.missionboss', (e) => { if (teamOf(e.source.characterName) === teamOf(Me.Name)) Object.assign(missionBoss, { name: String((e.data || {}).name || ''), until: now() + 3 * 3600e3 }); });
// RAID ACROSS A RESTART (2026-10-07 08:19: MemWatch restarted L2Swarm in the middle of the Chertuba fight; after the login the team ran
// from its own boss — no raid mode any more, so the raid-boss rule said "outside a raid"). The leader writes Logs/raid_active_<team>.json at
// the mission start and marks it done at the result; at startup every window of that team takes the boss as allowed for 30 min when the
// file is less than 45 min old and not done — they fight it (self-defence / help) instead of running.
const RAID_ACTIVE_FILE = (team) => `${SWARM_ROOT}/Logs/raid_active_${String(team).toLowerCase()}.json`;
// phase (2026-10-09): 'trip' at the mission start, 'fight' at the engage step — after the 11:02 reload every window said "Elf Renoa was being
// raided" while the team still stood at Talakin's spot waiting to set off for it
function raidActiveWrite(name, done, phase) { try { File.WriteAllText(RAID_ACTIVE_FILE(teamOf(Me.Name)), JSON.stringify({ team: teamOf(Me.Name), boss: name, at: new Date().toISOString(), done: !!done, phase: phase || (done ? 'done' : 'trip') })); } catch (e) { } }
(async () => {
  while (!IsCharacterReady()) await sleep(1000);                     // at login the script starts before the character is selected
  await sleep(2000);
  try {
    const j = JSON.parse(File.ReadAllText(RAID_ACTIVE_FILE(teamOf(Me.Name))));
    if (j && !j.done && j.boss && now() - Date.parse(j.at) < 45 * 60000) {
      Object.assign(missionBoss, { name: j.boss, until: now() + 30 * 60000 });
      const ago = Math.round((now() - Date.parse(j.at)) / 60000);
      note(j.phase === 'trip' ? `raid across a restart: ${j.boss} was the target of the raid trip (${ago} min ago) — it counts as our boss (no running from it)`
        : `raid across a restart: ${j.boss} was being raided (${ago} min ago) — fighting it, not running`, true);
    }
  } catch (e) { }
})();
const isMissionBoss = (n) => !!missionBoss.name && now() < missionBoss.until && missionBoss.name.toLowerCase() === String(n).toLowerCase();
const raidBossOutsideRaid = (m) => !!(m && isRaidBossMob(m) && !isMissionBoss(m.Name) && !(inRaid() && state.bossName && String(state.bossName).toLowerCase() === String(m.Name).toLowerCase()));
// RAID-TITLED MONSTERS (user 2026-10-09 17:35: "all raid monsters, even minions, have 'raid' in their title, so Dagger1 should never have
// attacked them"): outside a raid / mission a monster whose title says Raid (boss OR minion) is never a target (hunt, assist, help, pull);
// one that actually hits me is still fought back / escaped from like any attacker (the boss itself stays never-fought via raidBossOutsideRaid)
const raidTitled = (m) => { let t = ''; try { t = String((m && m.Title) || ''); } catch (e) { } return /\braid\b/i.test(t); };
const raidTitledOutsideRaid = (m) => !!(m && raidTitled(m) && !inRaid() && state.mode !== 'mission' && !isMissionBoss(m.Name));
const ignoredMob = (m) => !!(m && (ignoredMobHard(m) || inZoneHole(m.X, m.Y, m.Z, m.Name) || raidTitledOutsideRaid(m)));
// never fought, not even when it hits me (Treasure Chest, a raid boss outside its raid); the spot editor's exclusions (inZoneHole) are only
// "never a target": a monster from an excluded area that actually hits me is fought back (self-defence), user 2026-10-07
const ignoredMobHard = (m) => !!(m && ((CONFIG.lead && CONFIG.lead.ignoreMobs && CONFIG.lead.ignoreMobs.test(String(m.Name || ''))) || raidBossOutsideRaid(m)));
// ZONE EDITOR (user 2026-10-07): exclusion polygons drawn in a hunting zone ("obstacles, cliffs") — monsters inside one are never fought
// (no target, no self-defence, no help; L2Swarm's own target there is cancelled by the ignore loop). L2Swarm's own .zmap only gets the
// outer polygon (its exclusion format could not be verified), so the exclusions are enforced here.
function inPolygon(x, y, P) {
  let inside = false;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[i], b = P[j];
    if (((a.y > y) !== (b.y > y)) && (x < (b.x - a.x) * (y - a.y) / ((b.y - a.y) || 1e-9) + a.x)) inside = !inside;
  }
  return inside;
}
// SPOT EDITOR (user 2026-10-07, full-screen map): also round exclusions (circles {x,y,z?,r}) and monster kinds never fought in a spot
// (avoidMobs, within the spot's area + 3000); points / circles drawn with a height only count on that floor (towers, caves: +-400 / +-500).
const zoneHoles = { at: 0, list: [], circles: [], mobs: [] };
function inZoneHole(x, y, z, name) {
  if (!isFinite(x) || !isFinite(y)) return false;
  if (now() - zoneHoles.at > 60000) {
    zoneHoles.at = now();
    try {
      const t = teamOf(Me.Name), mine = (zz) => zz.enabled !== false && (Array.isArray(zz.teams) ? (zz.teams.includes('all') || zz.teams.includes(t) || zz.teams.includes(CONFIG.leader)) : (!zz.team || zz.team === 'all' || zz.team === t || zz.team === CONFIG.leader));
      const zs = customZones().filter(mine);
      zoneHoles.list = [].concat(...zs.filter(zz => zz.holes).map(zz => zz.holes)).filter(h => Array.isArray(h) && h.length >= 3).map(h => {
        const hz = h.map(p => p.z).filter(v => isFinite(v));
        h.zMin = hz.length ? Math.min(...hz) - 400 : null; h.zMax = hz.length ? Math.max(...hz) + 400 : null; return h;
      });
      zoneHoles.circles = [].concat(...zs.filter(zz => Array.isArray(zz.circles)).map(zz => zz.circles)).filter(c => c && isFinite(c.x) && isFinite(c.y) && c.r > 0);
      zoneHoles.mobs = zs.filter(zz => Array.isArray(zz.avoidMobs) && zz.avoidMobs.length).map(zz => ({ x: zz.x, y: zz.y, r: (num(zz.radius) || 3000) + 3000, names: zz.avoidMobs.map(n => String(n).toLowerCase()) }));
    } catch (e) { zoneHoles.list = []; zoneHoles.circles = []; zoneHoles.mobs = []; }
  }
  const zOk = (lo, hi) => lo == null || !isFinite(z) || (z >= lo && z <= hi);
  for (const h of zoneHoles.list) if (Math.abs(h[0].x - x) < 30000 && zOk(h.zMin, h.zMax) && inPolygon(x, y, h)) return true;
  for (const c of zoneHoles.circles) if (Math.hypot(c.x - x, c.y - y) <= c.r && (!isFinite(c.z) || zOk(c.z - 500, c.z + 500))) return true;
  if (name) { const n = String(name).toLowerCase(); for (const a of zoneHoles.mobs) if (a.names.includes(n) && Math.hypot(a.x - x, a.y - y) <= a.r) return true; }
  return false;
}
/** mage / melee / small — what kind of team mine is (for zones drawn for one kind of team). */
function teamKind() {
  const names = [Me.Name].concat(teamNames());
  if (names.length <= 3) return 'small';
  const casters = names.filter(n => /^(nuker|necromancer)$/.test(CONFIG.roster[n] || '')).length;
  return casters >= names.length / 2 ? 'mage' : 'melee';
}
function log(msg) { console.log(`[${state.role}] ${msg}`); }

async function cast(skillId, delayAfterMs = 800) {
  if (!hiveSkillsOn()) { await sleep(Math.min(delayAfterMs, 1000)); return; }   // HIVESW-2026-10-15 (raid helper casts: necro / inspector / old routines)
  if (!skillId || !SkillsList.GetItemByID(skillId)) return;   // ikke lært endnu: spring over
  Send.RequestMagicSkillUse(skillId);
  await sleep(delayAfterMs);
}

async function castOn(creature, skillId, delayAfterMs = 800) {
  if (!creature || !skillId) return;
  if (!hiveSkillsOn()) { await sleep(Math.min(delayAfterMs, 1000)); return; }   // HIVESW-2026-10-15
  { const m = mobById(creature.objId); if (m && !canSee(m)) { wallRefused('casting at', m); await sleep(200); return; } }   // WALLSIGHT-2026-10-24: never cast at a monster through a wall
  Send.Action(creature.objId);
  await sleep(350);
  await cast(skillId, delayAfterMs);
}

function findItem(itemId) {
  try { return Inventory.GetItemByID(itemId); } catch (e) { return null; }
}

// WALLSIGHT-2026-10-24 (owner: "you HAVE to see the monsters and never through a wall ... walls are COMPLETE blockers in Lineage 2 — you can not
// shoot, interact or do anything through a wall", memory walls-block-everything): line of sight from me on the L2J geodata (brain host GeoSight =
// docs/plan/tools/geopath.js sight: wall bits + other floors block, a slope / step does not). Cached 1.5 s per (my cell, its cell). No GeoSight
// (the old in-process engine) = the old behaviour (seen); no geodata there (null) = seen only when close (<= 250).
// SEECOST-2026-10-24 (19:07-20:00 after the deploy: brain workers 80-100 % ELU, watchdog kills): one GeoSight costs 80-250 µs on multi-floor
// geodata (Cruma), and huntTarget / nearestMonster asked it for EVERY monster in view several times a second. Now: nothing beyond SEE_FAR
// (no action reaches that far; the check runs again when we are close), a coarse 2 s cache and at most SEE_BUDGET geodata checks per second.
const SEE_FAR = 3000, SEE_BUDGET = 40;   // 40 x ~200 µs = 8 ms a second per character at worst (9 per worker: ~7 % of a worker)
const SEE = { c: {}, cn: 0, refused: 0, saidAt: 0, sec: 0, n: 0, over: 0 };   // c: plain object, no Map (L2Swarm host: Map = the world map type)
function canSee(c) {
  try {
    if (!c) return false;
    const x = num(c.X !== undefined ? c.X : c.x), y = num(c.Y !== undefined ? c.Y : c.y), zr = c.Z !== undefined ? c.Z : c.z, z = (zr === undefined || zr === null || !isFinite(Number(zr))) ? Me.Z : num(zr);
    const d = Math.hypot(x - Me.X, y - Me.Y);
    if (d <= 100 && Math.abs(z - Me.Z) < 250) return true;
    if (typeof GeoSight !== 'function' || d > SEE_FAR) return true;
    const key = `${Math.round(Me.X / 128)},${Math.round(Me.Y / 128)},${Math.round(Me.Z / 128)}>${Math.round(x / 128)},${Math.round(y / 128)},${Math.round(z / 128)}`;
    const hit = SEE.c[key]; if (hit && now() - hit.at < 2000) return hit.v;
    const sec = Math.floor(now() / 1000); if (sec !== SEE.sec) { SEE.sec = sec; SEE.n = 0; }
    if (++SEE.n > SEE_BUDGET) { SEE.over++; return d <= 600; }      // over budget this second: only what is close counts as seen
    let v = null; try { v = GeoSight(Me.X, Me.Y, Me.Z, x, y, z); } catch (e) { v = null; }
    const r = v === null || v === undefined ? true : !!v;   // no geodata here (an install without Geodata, a point off the grid): unknown is not a wall - the server still refuses a real one (#181)
    if (SEE.cn > 3000) { SEE.c = {}; SEE.cn = 0; }
    if (!SEE.c[key]) SEE.cn++; SEE.c[key] = { v: r, at: now() };
    return r;
  } catch (e) { return true; }
}
/** WALLWALK-2026-10-25: a monster behind a wall/hill is never hit through it, but we select it and walk to it (the server paths round),
 *  at most once a second - members used to stand still and join the fight seconds late (test_member_assist) */
const WALLWALK = { id: 0, at: 0 };
function wallApproach(o, m) { if (WALLWALK.id === o && now() - WALLWALK.at < 1000) return; WALLWALK.id = o; WALLWALK.at = now(); try { if (!Target || num(Target.objId) !== o) Send.Action(o); } catch (e) { } try { Send.MoveBackwardToLocation(Math.round(num(m.X)), Math.round(num(m.Y)), Math.round(num(m.Z))); } catch (e) { } }
/** a refused action through a wall: counted, told at most once a minute */
function wallRefused(what, c) { SEE.refused++; if (now() - SEE.saidAt > 60000) { SEE.saidAt = now(); note(`wall: not ${what} ${c && c.Name ? c.Name : 'that'} — a wall is between us (${SEE.refused} refused so far)`); } }
function nearestMonster(cx, cy, range) {
  let best = null, bestDist = range;
  try {
    snapMobs().forEach(crt => {
      if (crt.IsDead) return;
      const d = Math.hypot(crt.X - cx, crt.Y - cy);
      if (d < bestDist && canSee(crt)) { bestDist = d; best = crt; }   // SEECOST: the sight check only for a nearer candidate
    });
  } catch (e) { /* ignore */ }
  return best ? best.ref : null;                      // HOSTTOUCH: .ref (a live lookup) only for the winner
}

function countMobsNear(x, y, radius) {
  let n = 0;
  try { snapMobs().forEach(m => { if (!m.IsDead && Math.hypot(m.X - x, m.Y - y) <= radius) n++; }); } catch (e) { }
  return n;
}

function distTo(x, y) { return Math.hypot(Me.X - x, Me.Y - y); }

function destroyerNames() {
  return Object.entries(CONFIG.roster)
    .filter(([, role]) => role === 'destroyer')
    .map(([name]) => name);
}

/** Den ANDEN destroyer (min sparringspartner til HP-drain) */
// DRAIN PAIRS (2026-10-06: team 3 has 7 destroyers — "the first other destroyer" made all of them hit the same one): the destroyers of MY
// party, sorted by name, go in fixed pairs 1+2, 3+4, 5+6; an odd last one hits the one before him (a trio at the end).
function partnerDestroyer() {
  const inParty = {};
  try { PartyList.forEach(m => { inParty[m.Name] = m; }); } catch (e) { }
  const list = destroyerNames().filter(n => n === Me.Name || inParty[n]).sort();
  const i = list.indexOf(Me.Name);
  if (i < 0 || list.length < 2) return null;
  const other = i % 2 === 0 ? (list[i + 1] || list[i - 1]) : list[i - 1];
  const m = other ? inParty[other] : null;
  return m && !m.IsDead ? m : null;
}

