    const d = e.data || {}; if (d.to !== Me.Name || e.source.characterName !== CONFIG.leader || isLeader()) return;
    if (d.phase === 'done' || d.phase === 'failed') { if (RESCIN.at) note(`rescue: ${CONFIG.leader} — ${d.phase === 'done' ? 'rescue over' : 'cannot come: ' + (d.why || '')}`); Object.assign(RESCIN, { at: 0, phase: d.phase }); return; }
    if (!RESCIN.at) note(`rescue: ${CONFIG.leader} is coming — ${d.text || ''} (ETA ${Math.round(num(d.etaSec) / 60)} min)`, true);
    Object.assign(RESCIN, { by: CONFIG.leader, text: String(d.text || ''), etaAt: now() + num(d.etaSec) * 1000, at: now(), phase: String(d.phase || ''), step: String(d.step || '') });
