    // teleported away mid-walk (fx the restock trip took the party to Giran) or the restock flow has the party: stop at once
    if (d > CONFIG.travel.maxWalk || partyTripBusy) { note(`leader: stopped the team walk to ${P(x, y)} — ${partyTripBusy ? 'restock trip has the party' : Math.round(d / 1000) + 'k away now (teleported)'}`, true); intentDone('lead team', false, 'stopped'); return false; }
