async function walkTo(x, y, z, dist, timeoutMs, abortIn) {
  if (typeof onRouteWalk === 'function' && onRouteWalk()) return false;        // walking the user's route: no other walks (cliffs)
  const g0 = control.gen;
  const abort = () => (abortIn && abortIn()) || interrupted(g0);   // priority: a more important task took over -> stop walking
  await settleAfterPort();
  if (teamLeadActive() && distTo(x, y) > CONFIG.together.stageDist && !state.inTravel && !state.gkBusy) {
    if (!state.inTravel && distTo(x, y) > CONFIG.travel.minDist) { try { await teleportNear(x, y, state.task || ''); } catch (e) { logError('teleportNear', e); } }
    if (distTo(x, y) > CONFIG.travel.maxWalk) { note(`travel: target ${P(x, y)} is still ${Math.round(distTo(x, y))} away after teleport attempt — will NOT walk that far (max ${CONFIG.travel.maxWalk})`, true); intent('walk', 'refused: too far to walk', { x, y, z }); intentDone('walk', false, 'too far — no teleport route'); return false; }
    return leadTeamWalk(x, y, z, dist, timeoutMs, abort);
  }
  // leader design: members never teleport on their own (only the left-behind .giran); they walk or wait for the leader
  if (!state.inTravel && !state.gkBusy && distTo(x, y) > CONFIG.travel.minDist && !(leadMode() && !isLeader())) {
    try { await teleportNear(x, y, state.task || ''); } catch (e) { logError('teleportNear', e); }
  }
  // HARD LIMIT, no exceptions: never walk further than maxWalk (2026-10-03: a leftover 'busy' flag skipped this check and Tank1
  // walked out of Giran towards a spot 140k away, with the whole party following). No teleport = stay and let the caller try again.
  if (distTo(x, y) > CONFIG.travel.maxWalk) {
    note(`travel: target ${P(x, y)} is ${Math.round(distTo(x, y) / 1000)}k away — will NOT walk that far (max ${Math.round(CONFIG.travel.maxWalk / 1000)}k); needs a teleport`, true);
    intent('walk', 'refused: too far to walk', { x, y, z }); intentDone('walk', false, `${Math.round(distTo(x, y) / 1000)}k — too far to walk, no teleport`);
    return false;
  }
  if (await refuseTownExit(x, y, z, 'walk')) return false;             // after the teleport attempt: still in a town and the target is outside it
  intent('walk', `to ${P(x, y, z)} (within ${dist})`, { x, y, z });
  let r = await walkToInner(x, y, z, dist, timeoutMs, abort);
  // OWNER 2026-10-13 19:10 (3D): in a mapped multi-floor dungeon a walk to a point on another floor is not "arrived" at the right x,y
  if (r && isFinite(z) && dist <= 800) { try { const fb = typeof rsmFloorBand === 'function' ? rsmFloorBand(dungeonRooms(), x, y, z) : null; if (fb && (Me.Z < fb[0] || Me.Z > fb[1])) { r = false; note(`walk: at ${P(x, y)} but on another floor (z ${Math.round(Me.Z)}, target ${Math.round(z)})`); } } catch (e) { } }
  intentDone('walk', r, r ? 'arrived' : `not there — ${Math.round(distTo(x, y))} left`);
  return r;
}
