    const f = `${DSP.dir()}\\results.json`; let j = {}; try { if (File.Exists(f)) j = JSON.parse(File.ReadAllText(f)) || {}; } catch (e) { }
    const o = j[key] || { runs: 0, oks: 0 }; o.runs++; if (res.ok) o.oks++;
