/** Modtager: stå stille og accepter trade fra giveren. */
async function receiveItems(d) {
  const T = CONFIG.gear.tradeTimeoutMs;
  tradeState = { role: 'take', other: d.giver, until: now() + T * 2, what: d.what || tradeWhat(d.items), since: now(), stage: 'waiting', stageAt: now(), tries: 0, step: d.step || '', tok: d.tok ? String(d.tok) : '' };
  setTask(`trade <- `);
  const wasEnabled = IsEnabled;
  try {
    stopCombatG();
    if (IsEnabled) DisableBot();
    // TRADEROOM-2026-10-23: no room in my bag -> refuse at once with the reason (the giver stops asking), never open a trade that cannot finish
    { const nk = Array.isArray(d.items) ? d.items.filter(i => !i.adena && !(i.stack && i.id && itemCount(i.id) > 0)).length : 1;
      const adenaOnly = d.step === 'fund' || (Array.isArray(d.items) ? d.items.length > 0 && d.items.every(i => i.adena) : /^\s*[\d,.]+\s*adena\s*$/i.test(String(d.what || '')));   // adena needs no slot / weight
      const room = d.added || adenaOnly ? { ok: true } : tradeRoomDecide(tradeRoomLive(), null, nk, now());
      if (!room.ok) {
        tradeLog(`take ${d.giver}: refused — ${room.why}`); note(`trade <- ${d.giver}: refused — my ${room.why} (sell or store things first)`, true);
        try { App.emit('swarm.trade.refuse', { giver: d.giver, receiver: Me.Name, why: room.why }); } catch (e) { }
        if (tradeState) tradeState.done = 'refused';
        return tradeEnd({ ok: false, full: true, msg: room.why });
      } }
    // an open shop window makes the server answer the giver "on another task" (msg 142, Doombringer1 2026-10-03): close it first
    try { Send.RequestBuySellUIClose(); } catch (e) { }
    try { Send.StopMove(); Options.ActiveFollow = false; } catch (e) { }   // stand still for the trade (moving receivers answered #22)
    standUp();
    // keep saying "yes" until the window is open — TRADEEV: at most every 4 s and never once it opened (#120 / trade.added): with 3-6 s
    // agent ticks the old 1.5 s loop kept answering into the open trade (the server answers that with a TradeDone(0) to my client)
    tradeLog(`take ${d.giver}: waiting for the trade${d.added ? ' (it is already open: confirming)' : ''}`);
    if (d.added && tradeState) { tradeState.started = true; tradeState.startedAt = now(); tradeState.added = now(); try { Send.TradeDone(1); } catch (e) { } }
    let rc = 0;
    const acceptLoop = setInterval(() => {
      if (!tradeState) return;
      if (tradeBegun() && !tradeState.started) { tradeState.started = true; tradeState.startedAt = now(); }
      if (!tradeState.started) { acceptTrade(); return; }
      // re-confirm every 3 s after the giver added its items until the server says done (a confirm before the item landed is reset)
      if (tradeState.added && !tradeState.done && now() - (tradeState.rcAt || tradeState.added) >= TRADEEV.reconfirmMs && rc < TRADEEV.reconfirmMax) { rc++; tradeState.rcAt = now(); try { Send.TradeDone(1); } catch (e) { } }
    }, 1000);
    let done;
    try { done = await waitTrade('done', T * 2); } finally { SCHED.clear(acceptLoop); }
    tradeLog(`take ${d.giver}: ${done || 'timeout'}`);
    return tradeEnd({ ok: !!done, msg: done || 'timeout' });
  } finally {
    if (!tradeState || !tradeState.done) { try { Send.TradeDone(0); } catch (e) { } }   // never leave a trade hanging (it blocks all NPCs)
    tradeQuiet();                                                     // TRADEEV: this session's late events must not end the next one
    tradeFinish();
    tradeState = null;
    if (wasEnabled && !IsEnabled) EnableBot();
    if (!isLeader()) { try { Options.FollowName = CONFIG.leader; Options.ActiveFollow = followOk(!memberRoute.id); } catch (e) { } }   // follow again after standing still for the trade
    if (leadMode()) setTimeout(() => { try { shotsOn = 0; enableShots(); } catch (e) { } }, 1500);   // supplies arrived: switch shots on
    else setTimeout(() => equipAll(6).catch(e => logError('equipAll', e)), 1500);
  }
}

// TRADEWALL-2026-10-20: the giver found no wall-free way to me -> I walk to it over the wall-checked path (only while I wait for ITS trade)
App.on('swarm.trade.come', (e) => {
  const d = e.data || {};
  if (!d.giver || !CONFIG.roster[d.giver] || !tradeState || tradeState.role !== 'take' || tradeState.other !== d.giver || tradeState.started) return;
  if (!isFinite(Number(d.x)) || Math.hypot(Number(d.x) - Me.X, Number(d.y) - Me.Y) > 2500) return;
  if (tradeState.coming && now() - tradeState.coming < 20000) return;
  tradeState.coming = now();
  tradeLog(`take ${d.giver}: it has no walkable way to me — walking to it`);
  (async () => {
    let gw = null; try { gw = await geoWalk(Number(d.x), Number(d.y), Number(d.z) || Me.Z, 80, 25000); } catch (er) { gw = null; }
    if (gw === null) { try { await walkDirect(Number(d.x), Number(d.y), Number(d.z) || Me.Z, 100, 8000, null, true); } catch (er) { } }
    try { Send.StopMove(); } catch (er) { }
  })().catch(er => logError('trade come', er));
});

// --- CROSS-TEAM FUNDING (user 2026-10-06 23:45: "Tank1 should give their leader some adena so they can be equipped — make it work") -------
// Mail does not work: MCP's mail_quick_send (RequestQuickSendPost) is silently ignored by the server, and a received mail's id cannot be read
// from a script (no mail list in the API) to claim it. So: a trade in Giran. The richest team leader (> richAbove), whenever he stands in
// Giran outside a raid, calls every character of ANOTHER team that reported less than minAdena (and got nothing in the last 24 h). The poor
// team's leader takes his team to Giran with .giran (only when not in a raid / mission), everyone meets at the Giran start, the giver
// trades each one its share (team leader more: he buys the team's supplies), then the giver releases and both teams go on.
// TOP-UP (user 2026-10-07: "make sure Tank1 gives adena to the rest of the teams so they can all restock for no grade and D grade"):
// every character of another team is filled up to its target (leader 8M: he buys shots/potions/scrolls for the whole team; member 3M:
// its own No-Grade / D-grade gear) when it is more than 500k below it, at most every 6 h. The giver never goes below richAbove.
// USER 2026-10-08 22:08 ("Why should Destroyer8 and Destroyer4 come for adena? They are farming, so the team should NOT be waiting for them"):
// nobody is called away from hunting any more. The giver only hands out to characters that are ALREADY in the fund town (live position),
// waits at most waitMs (90 s) for them to reach the meeting point, and a receiving team is never taken to Giran for a hand-out.
var FUND = { on: true, richAbove: 30000000, leaderTarget: 8000000, memberTarget: 3000000, slack: 500000, minGive: 200000, everyMs: 30 * 60000, brokeBelow: 500000, waitMs: 90000, town: 'Giran' };
// FUND RULES (user 2026-10-12: "the adena from another party should be 100% customizable, not something we can assume"): Scripts/data/
// fund_rules.json (dashboard -> Adena page), read every 30 s. Missing file = the values above (the behaviour until today).
//  { on, town, everyMin, minGive, slack, brokeBelow,
//    givers: { mode: 'auto' (any rich party leader) | 'list' | 'none', list: [names], keepAtLeast },
//    defaults: { leaderTarget, memberTarget, clanLeaderTarget },
//    parties: { <leader>: { receive: true|false, leaderTarget?, memberTarget? } },  chars: { <Name>: { target } }   (target 0 = never receives) }
const FUNDR = { at: 0, j: null };
function fundRules() {
  if (FUNDR.j && now() - FUNDR.at < 30000) return FUNDR.j;
  FUNDR.at = now();
  let j = null; try { j = JSON.parse(String(File.ReadAllText(`${__SCRIPTS__}\\data\\fund_rules.json`)).replace(/^\uFEFF/, '')); } catch (e) { j = null; }
  FUNDR.j = j && typeof j === 'object' ? j : {};
  const r = FUNDR.j, n = (v, d) => (v === undefined || v === null || v === '' || !isFinite(Number(v))) ? d : Number(v);
  FUND.on = r.on !== undefined ? !!r.on : true;
  FUND.town = r.town || 'Giran';
  FUND.everyMs = n(r.everyMin, 30) * 60000; FUND.minGive = n(r.minGive, 200000); FUND.slack = n(r.slack, 500000); FUND.brokeBelow = n(r.brokeBelow, 500000);
  FUND.richAbove = n(r.givers && r.givers.keepAtLeast, 30000000);
  FUND.leaderTarget = n(r.defaults && r.defaults.leaderTarget, 8000000); FUND.memberTarget = n(r.defaults && r.defaults.memberTarget, 3000000);
  return FUNDR.j;
}
// FUNDGIVERS-PURE-BEGIN (owner 2026-10-13: "if someone should give them adena, it must also configure the player you set up (the giver)"):
// a RECEIVING party may have its own givers rule (fund_rules.json parties.<leader>.givers = { mode: 'auto' | 'list' | 'none', list }); a party
