    { const t0 = now(); while (!takeControl('fund trip', PRIO.ORDER) && now() - t0 < FUND.waitMs - 30000 && state.running) await sleep(5000); }
    if (control.owner !== 'fund trip') { note(`fund: ${d.giver} has adena for us, but ${control.owner || 'something'} kept control — next round`, true); fund.until = 0; return; }
