  const pts = (Q) => Array.isArray(Q) ? Q.map(p => Array.isArray(p) ? [Number(p[0]), Number(p[1])] : [Number(p && p.x), Number(p && p.y)]).filter(p => isFinite(p[0]) && isFinite(p[1])) : [];
  const F = pts(a.fight); if (F.length < 3) return null;
