  try { if (typeof rgFollow !== 'undefined' && rgFollow.pts && rgFollow.pts.length) { rgFollow.pts = []; done.push('old follow route cleared'); } if (state.route && state.route.kind === 'follow') state.route = null; } catch (e) { }
