  const rcT = typeof rcOn === 'function' && rcOn();   // CIRCUIT 24/7 round 2 (owner 17:30: one straggler 53 km behind made the whole trip fail)
  const all = teamSpread(), lim = leadMode() && !rcT ? 1e12 : CONFIG.together.ignoreBeyond;
