    if (have <= 0) skip.push({ name: a + ' adena', why: 'no adena in my bag' });
    else give.push({ adena: true, id: 57, objId: Number(st[0].objId), count: Math.min(a, have), name: `${Math.min(a, have)} adena`, stack: true, short: a > have });
