    if (o.state === 'none') { if (CLANHAND.sig === sig) return; CLANHAND.sig = sig; if (!File.Exists(clanHandFile())) return; }
    else { if (CLANHAND.sig === sig && now() - CLANHAND.wroteAt < CLANHAND_CFG.statusRefreshMs) return; CLANHAND.sig = sig; }
