      for (let i = 0; i < n && r.left() > 0; i++) { r.d(); const id = r.d(); r.d(); r.q(); const en = mkItemTail(r); r.d(); const price = r.q(); r.q(); const want = r.q(); items.push({ id, count: want, price, enchant: en }); }
