  setTask('crystallizing (owner order)');
  cryLog(`order: ${p.ids.length} piece(s) [${p.ids.join(',')}]${t.enchanted ? ' +enchanted' : ''}${t.special ? ' +special' : ''}; Crystallize level ${skill}`);
