    orders.forEach(o => (o.items || []).forEach(it => { const k = o.id + ':' + it.id; const left = num(it.count) - num(S.done[k]); if (left > 0 && num(S.fails[k]) < 3) take[k] = { id: num(it.id), left, ench: !!o.enchanted, name: it.name || String(it.id), picked: [] }; }));
