  const j = rcpJudge(scroll, ent, { createLvl: stashSkillLvl(172), commonLvl: stashSkillLvl(1320), known: book ? book.ids : null });
  if (!j.ok) return `${name}: ${j.why}`;
  const before = itemCount(scroll), t0 = now();
