    note(`clan quest ${d.id}: ${who} has the item — back to normal leveling`, true);
    Object.assign(cqHunt, { id: null, item: 0 }); autoLvl.forceSpot = null; autoLvl.spot = null; if (autoLvl.active) autoLvl.stop = true;
