    const L = livePos[CONFIG.leader]; if (!d.door && L && Math.hypot((L.X || 0) - Me.X, (L.Y || 0) - Me.Y) < 1500 && (L.Z == null || Math.abs(L.Z - Me.Z) < 600)) return;   // NAVATLAS2: same floor only
