    if (e) { objId = num(e.objId); x = Math.round(e.X); y = Math.round(e.Y); if (e.IsDead) st = 'dead'; else { st = 'alive'; hp = num(e.HpPercent) > 0 ? Math.round(num(e.HpPercent)) : null; SIEGE.cmdSeenAlive[key] = now(); } }
    else if (sn && now() - sn.at < 15000) { st = sn.status; hp = sn.hp; objId = sn.objId || 0; if (sn.x) { x = sn.x; y = sn.y; } }
    if (st === 'dead') SIEGE.cmdDead[key] = SIEGE.cmdDead[key] || now();
