    if (st === 'unknown' && SIEGE.cmdDead[key]) st = 'dead';
    if (st === 'alive' && SIEGE.cmdDead[key]) delete SIEGE.cmdDead[key];              // respawned (not all killed within 10 min: they reset)
    out.push({ key, kind, name, npcId: num(npcId), objId, x, y, z: p.z, status: st, hp, party: party || '', focus: Object.values(SIEGE.focus).some(f => f && f.objId && f.objId === objId) });
