    const there = await travelToSpot({ name: `siege: ${t.name}`, levelMin: 1, levelMax: 99, center: { x: stg.x, y: stg.y, z: stg.z }, radius: 800, near: true, noHub: true });
    if (!alive()) { end('stopped'); return; }
