      const assigned = objs.find(o => (o.kind === 'commander' || o.kind === 'tower') && o.party === Me.Name && o.status !== 'dead');
      const open = objs.filter(o => (o.kind === 'commander' || o.kind === 'tower') && o.status !== 'dead');
      let goal = assigned || open.sort((a, b) => Math.hypot(a.x - Me.X, a.y - Me.Y) - Math.hypot(b.x - Me.X, b.y - Me.Y))[0] || null;
      const c = t.pos, dMe = Math.hypot(Me.X - c.x, Me.Y - c.y);
