      if (goal.key !== curKey) { curKey = goal.key; siegeEvent(`party ${Me.Name}: ${goal.kind === 'gate' ? 'breaking ' : 'attacking '}${goal.name}`); }
      SIEGE.partyTask[Me.Name] = `${goal.kind === 'gate' ? 'gate' : 'kill'}: ${goal.name}`;
