    { const pre = clanSkillPrecheck(); clanAutoNote('skill', pre.msg); if (!pre.ok) return; }   // CLANAUTO: no daily trip that the server refuses anyway
    st.day = day; File.WriteAllText(F, JSON.stringify(st));
