  pstStep('travel', 'walk', { info: `${Math.round(Math.hypot(spot.center.x - Me.X, spot.center.y - Me.Y))} to the centre` });
  try { walked = await walkTo(spot.center.x, spot.center.y, spot.center.z, 500, 600000); } finally { state.walkOnly = false; }
  if (walked) return true;
  // could not walk to the very centre (2026-10-04: Ruins of Despair's centre lies in a pit 4 km from the landing, unreachable by the
  // path finder -> the spot got banned and the trio left its route). Inside the hunting square is good enough: hunt here.
  const left = Math.hypot(spot.center.x - Me.X, spot.center.y - Me.Y);
  if (left < 6000) { note(`autolevel: could not reach the centre of ${spot.name}, but I am ${Math.round(left)} from it — hunting here`, !autoLvl.solo); return true; }
