    appendShared(TPOOL.log, `${new Date().toISOString()} [${Me.Name}] pool busy=${mw - aw} min=${nw} io busy=${mio - aio} timerLate=${late}ms sched=${sOn ? 'on' : 'OFF'} jobs=${S.jobs} skippedBusy=${S.skippedBusy} errors=${S.errors} maxTick=${S.maxTickMs}ms ${gcLine()} creatures=${SNAP.st.n}\r\n`);
