// GC COUNTERS on the threadpool.log line (perf audit 2026-10-07 M3; the .NET CLR Memory perf counters are not installed on this PC):
// collections per generation since process start, (+ since the previous line = 10 s), and the managed heap. More than ~1 Gen2 per 10 s,
// or a Gen2 rate rising with uptime = GC pressure (audit F2 / F7).
const GCT = (() => { try { return __extended_host_functions.type('System.GC'); } catch (e) { return null; } })();
let gcPrev = null;
function gcLine() {
  if (!GCT) return 'gc=n/a';
  try {
    const c = [Number(GCT.CollectionCount(0)), Number(GCT.CollectionCount(1)), Number(GCT.CollectionCount(2))];
    const d = gcPrev ? c.map((v, i) => v - gcPrev[i]) : [0, 0, 0]; gcPrev = c;
    return `gc0/1/2=${c.join('/')} (+${d.join('/')}) heap=${Math.round(Number(GCT.GetTotalMemory(false)) / 1048576)}MB`;
  } catch (e) { return 'gc=err ' + String(e && e.message || e).slice(0, 60); }
}
// SCHEDULER PROFILE (perf audit 2026-10-07 M2): every window sums each job's synchronous ms (SCHED above); every 60 s the main leader's
// window writes its top 10 jobs + its totals to Logs/sched_top.log, then every window resets its counters. "% core" = scheduler tick time
// of THIS window as a share of one core (async continuations after an await are not counted; they run outside the ticks).
const SCHED_TOP_LOG = SWARM_ROOT + '\\Logs\\sched_top.log';
// MORE ENGINES IN THE PROFILE (CPU audit 2026-10-09): Logs/sched_prof.json = { "names": ["Tank1", "Destroyer1", "Bishop1", "Necro1"] | "all",
// "until": "2026-10-09T12:00:00Z" } -> those windows write the same 60 s report as the main leader (+ a "state writer" line with the ms of
// each part of the 2 s swarm_state writer). No reload / deploy needed: every window re-reads the file at most every 30 s. "until" is optional
// (without it: until the file is deleted). Delete the file (or let "until" pass) to stop.
const SCHEDPROF = { chk: 0, on: false };
function schedProfMe() {
  if (now() - SCHEDPROF.chk < 30000) return SCHEDPROF.on;
  SCHEDPROF.chk = now();
  let on = false;
  try {
    const f = SWARM_ROOT + '\\Logs\\sched_prof.json';
    if (File.Exists(f)) {
      const j = JSON.parse(String(File.ReadAllText(f)).replace(/^﻿/, '')), until = Date.parse(j.until || '') || 0, n = j.names;
      if (!until || now() < until) on = n === 'all' || (Array.isArray(n) && n.map(String).includes(String(Me.Name)));
    }
  } catch (e) { on = false; }
  SCHEDPROF.on = on;
  return on;
}
/** the state writer's part costs since the last report, one line ('' when nothing was measured) */
function swCostLine() {
  try {
    if (typeof SW === 'undefined' || !SW.cost.total) return '';
    const c = SW.cost, tot = c.total, runs = Math.max(1, tot[1]);
    const parts = Object.keys(c).filter(k => k !== 'total').sort((a, b) => c[b][0] - c[a][0]).map(k => `${k} ${c[k][0]}ms/${c[k][1]}`);
    return `  state writer: ${tot[0]} ms in ${tot[1]} runs (${(tot[0] / runs).toFixed(1)} ms/run), watched ${SW.watchedRuns}/${SW.runs} runs, avg ${Math.round(SW.bytes / Math.max(1, SW.runs) / 100) / 10} KB; ${parts.join(', ')}`;
  } catch (e) { return ''; }
}
setInterval(() => {
  try {
    if (Me.Name && (String(Me.Name) === String(CONFIG.mainLeader || CONFIG.leader) || schedProfMe())) {
      const S = SCHED.st, secs = Math.max(1, Math.round((Date.now() - S.profAt) / 1000)), T = SCHED.top(10), N = SNAP.st;
      const lines = [`${new Date().toISOString()} [${Me.Name}] ${secs}s: ticks ${S.ticks} = ${S.tickMs} ms (${(S.tickMs / secs / 10).toFixed(1)}% core), jobs ${T.total} ms sync, ${S.jobs} jobs; ` +
        `snapshot[${N.mode}] ${N.builds} builds (${N.json} json) / ${N.enums} enumerations ${N.ms} ms (${N.n} creatures), ${N.lookups} id lookups + ${N.refs} refs, host snaps ${hostSnap.st.calls} (${hostSnap.st.fails} failed);swarm.pos ${POSF.sent} targeted rounds (${POSF.targeted} sends) + ${POSF.broadcasts} broadcasts, ${Object.keys(posAcct).length} known accounts`];
      T.rows.forEach((r, i) => lines.push(`  ${String(i + 1).padStart(2)}. ${String(r.cost).padStart(6)} ms ${String(r.runs).padStart(5)}x ${r.ms ? 'every ' + r.ms + ' ms' : ''}  ${r.label}`));
      const swl = swCostLine(); if (swl) lines.push(swl);
      appendShared(SCHED_TOP_LOG, lines.join('\r\n') + '\r\n');
    }
  } catch (e) { }
  try { if (typeof SW !== 'undefined') { SW.cost = {}; SW.runs = 0; SW.watchedRuns = 0; SW.bytes = 0; } } catch (e) { }
  try { SCHED.resetProf(); SNAP.st.builds = 0; SNAP.st.enums = 0; SNAP.st.ms = 0; SNAP.st.lookups = 0; SNAP.st.json = 0; SNAP.st.refs = 0; hostSnap.st.calls = 0; hostSnap.st.fails = 0; POSF.sent = 0; POSF.targeted = 0; POSF.broadcasts = 0; } catch (e) { }
}, 60000);

// V8 GARBAGE COLLECTION (docs/plan/dll_known_issues_2026-10-07.md, 2026-10-07 23:00): L2Swarm creates every V8 runtime without limits and
// never calls CollectGarbage; offline each engine kept ~85-90 MB after start/reload, one CollectGarbage(true) (~20 ms) took it to ~25 MB
// (~3.4 GB -> ~1 GB at 39 windows; it also releases the .NET objects JS still references). Each window: 90 s + random 0-120 s after start,
// then every 7 min; never during a raid / Kamaloka fight. Before/after heap -> Logs/v8gc.log. (Never set MaxRuntimeStackUsage/MaxRuntimeHeapSize.)
const V8GC = (() => {
  try {
    const H = __extended_host_functions;
    return H.cast(H.type('Microsoft.ClearScript.V8.V8ScriptEngine', 'ClearScript.V8'), H.type('Microsoft.ClearScript.ScriptEngine', 'ClearScript.Core').Current);
  } catch (e) { try { appendShared(SWARM_ROOT + '\\Logs\\v8gc.log', `${new Date().toISOString()} [${Me.Name}] no engine access: ${e.message}\r\n`); } catch (e2) { } return null; }
})();
function v8Collect(why) {
  if (!V8GC) return;
  try { if (inRaid() || (typeof inst !== 'undefined' && inst.on)) return; } catch (e) { }
  try {
    const mb = (x) => Math.round(Number(x) / 1048576);
    const b = V8GC.GetRuntimeHeapInfo(), t0 = now();
    V8GC.CollectGarbage(true);
    const a = V8GC.GetRuntimeHeapInfo();
    appendShared(SWARM_ROOT + '\\Logs\\v8gc.log', `${new Date().toISOString()} [${Me.Name}] ${why}: used ${mb(b.UsedHeapSize)} -> ${mb(a.UsedHeapSize)} MB, total ${mb(b.TotalHeapSize)} -> ${mb(a.TotalHeapSize)} MB, ${now() - t0} ms\r\n`);
  } catch (e) { try { appendShared(SWARM_ROOT + '\\Logs\\v8gc.log', `${new Date().toISOString()} [${Me.Name}] ${why} failed: ${e.message}\r\n`); } catch (e2) { } }
}
// 23:13 live: heaps only ~12 MB per window (472 -> 364 MB for all 39), one GC took ~400 ms -> every 20 min instead of 7
// 2026-10-09 (memory investigation): interval from runtime_flags.json v8gcMinutes (default 20, 5..120), checked every minute - no deploy needed.
// MEMCAP: objId-keyed caches that only lose entries on their own paths are cleared when they pass 2000 keys (cheap safety net).
let v8gcLast = 0;
setTimeout(() => {
  v8Collect('start'); v8gcLast = now();
  setInterval(() => {
    const m = Math.max(5, Math.min(120, Number(rtFlag('v8gcMinutes', 20)) || 20));
    if (now() - v8gcLast >= m * 60000) { v8gcLast = now(); v8Collect('periodic'); }
    try { [surTrack, huntBlack, pathCache].forEach(o => { let n = 0; for (const k in o) n++; if (n > 2000) for (const k in o) delete o[k]; }); } catch (e) { }
  }, 60000);
}, 90000 + Math.floor(Math.random() * 120000));

// ---------------------------------------------------------------------------
// HOLD SAMMEN  —  et holdmedlem der er langt fra sin leder (eller escort-ejer) i 30 s finder selv hen til den:
// > 8000: teleport til landingspunktet nærmest lederen + gå; ellers gå direkte. Bagefter følg igen.
// ---------------------------------------------------------------------------
const together = { farSince: 0, busy: false, lastTry: 0 };
setInterval(() => {
  if (leadMode()) return;                                              // 2026-10-04: members never walk off on their own; they follow
  if (!state.role || !IsCharacterReady() || Me.IsDead || isLeader() || together.busy) return;
  if (together.stayUntil && together.stayUntil > now()) {         // lederen er på vej til mig
    const pl = partyMember(CONFIG.leader);
    if (pl && Math.hypot(pl.X - Me.X, pl.Y - Me.Y) < 1500) { together.stayUntil = 0; try { Options.FollowName = CONFIG.leader; Options.ActiveFollow = followOk(!memberRoute.id); } catch (e) { } }
    return;
  }
  const target = escort.active && escort.owner && escort.owner !== Me.Name ? escort.owner : CONFIG.leader;
  if (!target || target === Me.Name) return;
  const busy = state.gkBusy || state.escaping || tradeState || questRun.active || (autoLvl.active && autoLvl.solo) || inRaid() || state.buffTurn || state.pauseWalk || !!errandNow();   // ERRAND-2026-10-23
  const p = partyMember(target);
  if (busy || !p || p.IsDead) { together.farSince = 0; return; }
  const d = Math.hypot(p.X - Me.X, p.Y - Me.Y);
  if (d < CONFIG.together.farDist) { together.farSince = 0; return; }
  if (!together.farSince) together.farSince = now();
  if (now() - together.farSince < CONFIG.together.afterMs || now() - together.lastTry < 60000) return;
  together.busy = true; together.lastTry = now();
  (async () => {
    note(`stay together: ${target} is ${Math.round(d)} away — heading to ${target}`, true);
    setTask(`regrouping with ${target}`);
    if (d > 8000) await escortGoToOwner(target);
    const q = partyMember(target);
    if (q && Math.hypot(q.X - Me.X, q.Y - Me.Y) > 600) await walkTo(q.X, q.Y, q.Z || Me.Z, 500, 240000);
    try { Options.FollowName = target; Options.ActiveFollow = followOk(!memberRoute.id); Options.FollowAtk = true; } catch (e) { }
    if (!IsEnabled) EnableBot();
    const q2 = partyMember(target);
    note(`stay together: ${q2 && Math.hypot(q2.X - Me.X, q2.Y - Me.Y) < 1500 ? 'reached ' + target + ' — following again' : 'did not quite get there — retrying in 1 min'}`);
  })().catch(e => logError('stay together', e)).finally(() => { together.busy = false; together.farSince = 0; });
}, 10000);

// --- Left behind (user rule 2026-10-04): a member that is alive, more than 15000 from the leader and not with him (respawned in a
// town after dying, or stranded) goes to Giran itself with .giran, waits at the Giran start and tells the leader, who then regroups the
// whole team in Giran and takes everyone out together.
// HALL SPLIT (2026-10-05): a Kamaloka Hall takes max 6. The leader ousts the others from the party for the run (benched), they wait in the
// town, and come back into the party afterwards. Benched windows: no follow, no left-behind reports, no stuck-follow; the leader's invite
// loop skips them until the bench ends.
const bench = { until: 0, names: [] };
function benchedHall(n) { return now() < bench.until && bench.names.includes(n || Me.Name); }
