      planProgSave(prog);
      SayToParty(`[plan] step ${idx + 1}/${n}: ${planStepSay(step)}`);
      intent('plan', `step ${idx + 1}/${n}: ${planStepSay(step)}`);
      let r;
      PLAN.seq = orderState.seq;                                           // an order that comes in from now on = the user took over
