      const ev = { amt, pct: Math.round(dp * 10000) / 10000, at: now(), why, lvl, up: up > 0 ? up : 0 };
      LIVEP.log.push(ev); if (LIVEP.log.length > 10) LIVEP.log.shift();
      LIVEP.hour.push(ev); LIVEP.hour = LIVEP.hour.filter(x => now() - x.at < 3600000).slice(-400);
