  const c = (mates || []).filter(m => m && m.name && m.name !== me && m.objId && !m.dead && m.d <= RECOM.range && !(m.have >= RECOM.max));
  c.sort((a, b) => ((a.have == null ? -1 : a.have) - (b.have == null ? -1 : b.have)) || (a.d - b.d) || (a.name < b.name ? -1 : 1));
