  if (!tree || !tree.classes) { out.why = 'no class tree (Scripts/data/class_tree.json)'; out.text = 'unknown'; return out; }
  const cur = cpClass(tree, me && me.classId);
  const e = cpEntry(plans, me && me.party, me && me.name);
