  const idx = out.chain.indexOf(Number(cur.id));
  if (idx < 0) { out.status = CP_STATUS.off; out.why = `${cur.name} is not on the plan (${out.chain.map(id => cpName(tree, id)).join(' > ')})`; out.text = 'off-plan'; return out; }
