App.on('swarm.leaderback.invite', (event) => {
  if (event.data.to !== Me.Name || teamOf(event.data.from) !== teamOf(Me.Name)) return;
  let inParty = false; try { PartyList.forEach(() => { inParty = true; }); } catch (e) { }
  if (inParty) return;
  note(`party: ${event.data.from} is inviting me back — accepting`);
  let n = 0;
  const iv = setInterval(() => { try { Send.RequestAnswerJoinParty(1); } catch (e) { } if (++n >= 8) SCHED.clear(iv); }, 1000);
});

/** The last dashboard state a teammate wrote (level + class name). */
function lastState(name) {
  try { const s = JSON.parse(File.ReadAllText(`${SWARM_ROOT}\\Logs\\swarm_state_${name}.json`)); return { level: num(s.level), cls: s.cls, classId: s.classId }; } catch (e) { return null; }
}

// ---------------------------------------------------------------------------
// FILE COMMAND CHANNEL (2026-10-08, after the MCP accept-loop death at 19:49: every MCP request hung, so the dashboard could not order
// anything). The dashboard (Dashboard/server.js commandRun) falls back to this when MCP does not answer: it writes the order to
// Logs\cmd\inbox.json = [{ id, at, from, to: ['Name'] | 'all' | 'team:<leader>', cmd: '!level' | '/stopcombat' | ..., via: 'party'|'say'|'command' }]
// (the last 2 minutes, atomic tmp+rename). Every window checks the file's time stamp once a second (File.Exists + GetLastWriteTimeUtc,
// nothing else when it did not change) and runs the entries addressed to it EXACTLY like the MCP path would:
//   !command via 'party' = SayToParty(!command) from this window (= MCP run_account_command #!command: the whole party hears it in handleSay);
//   !command via 'say' or no party = handleSay(Me.Name, !command) in this window only;
//   '/x' = the JS host call for the L2Swarm chat-box command (StopCombat, EnableBot, GoToPoint, Select, RunCommand('/sit'), ...);
//   anything else ('/config', '@login', ...) is answered "needs MCP".
// Each entry runs once: ids are remembered, an ack file Logs\cmd\ack_<id>_<Name>.json is written (and checked, so a script reload never
// runs it again), and entries older than 60 s are never run (acked 'expired'). Not ready (logging in) = tried again next second.
// CMDINBOX-BEGIN (no host calls in here: docs/plan/tools/test_cmd_inbox.js runs this block in node)
const CMD_INBOX_MAX_AGE = 60000;
// '/' L2Swarm chat-box commands the file channel can do itself (keep in sync with FILE_BOT in Dashboard/server.js - the test checks it)
const CMD_INBOX_HOST = { '/stopcombat': 'StopCombat', '/startcombat': 'StartCombat', '/enablebot': 'EnableBot', '/disablebot': 'DisableBot', '/moveto': 'GoToPoint', '/target': 'Select', '/attack': 'AttackTarget', '/loc': 'Loc' };
const CMD_INBOX_RUN = ['/sit', '/stand', '/unstuck', '/leave', '/run', '/walk', '/attackforce', '/attackround', '/invite', '/socialyes', '/socialdance', '/socialhello', '/startpoints', '/stoppoints', '/runmacro', '/clicklink', '/buyitem', '/ignore'];
function cmdInboxAddressed(e, me, teamOf) {
  const low = String(me || '').toLowerCase(); if (!low || !e) return false;
  const to = e.to;
  if (to === 'all') return true;
  if (typeof to === 'string') {
    if (/^team:/i.test(to)) { try { return String(teamOf(me) || '').toLowerCase() === to.slice(5).toLowerCase(); } catch (er) { return false; } }
    return to.toLowerCase() === low;
  }
  return Array.isArray(to) && to.some(n => String(n).toLowerCase() === low);
}
/** entries -> { run: entries for me to run now, expired: entries for me that are too old } (never one that was seen / acked before) */
function cmdInboxSelect(entries, me, nowMs, seen, teamOf) {
  const run = [], expired = [];
  (Array.isArray(entries) ? entries : []).forEach(e => {
    if (!e || typeof e !== 'object' || !/^[A-Za-z0-9_-]{4,64}$/.test(String(e.id || '')) || typeof e.cmd !== 'string' || !e.cmd.trim()) return;
    if (seen && seen[e.id]) return;
    if (!cmdInboxAddressed(e, me, teamOf)) return;
    const at = Number(e.at) || 0;
    if (!at || nowMs - at > CMD_INBOX_MAX_AGE || at - nowMs > CMD_INBOX_MAX_AGE) expired.push(e); else run.push(e);
  });
  run.sort((a, b) => Number(a.at) - Number(b.at));
  return { run, expired };
}
/** what to do for one entry: { kind: 'party'|'local'|'host'|'run'|'needs-mcp'|'bad', text, fn, args, why } */
function cmdInboxPlan(e, ctx) {
  const text = String(e.cmd || '').trim().replace(/^#(?=!)/, '');   // a party-chat '#' prefix is not part of the command
  if (!text || /[\r\n]/.test(text) || text.length > 300) return { kind: 'bad', why: 'one line, max 300 characters' };
  if (text[0] === '!') return (e.via === 'party' && ctx && ctx.inParty) ? { kind: 'party', text } : { kind: 'local', text };
  if (text[0] === '/') {
    const parts = text.split(/\s+/), w = parts[0].toLowerCase();
    // CMDFIX2-BOTPARTY-2026-10-12: L2Swarm's Exact rules (L2Swarm.Core.dll) - with extra text they fall through to public chat
    const EXACT = ['/help', '/?', '/sit', '/stand', '/unstuck', '/loc', '/time', '/run', '/walk', '/leave', '/partyinfo', '/instancezone', '/socialyes', '/socialdance', '/socialhello',
      '/ignore', '/trade', '/attack', '/attackforce', '/enablebot', '/disablebot', '/stopcombat', '/startcombat', '/startpoints', '/stoppoints', '/attackround'];
    if (EXACT.indexOf(w) >= 0 && parts.length > 1) return { kind: 'bad', why: `${w} takes no arguments (L2Swarm would say the whole line in public chat)` };
    const fn = CMD_INBOX_HOST[w];
    if (fn === 'GoToPoint') {
      const x = Number(parts[1]), y = Number(parts[2]);
      if (!isFinite(x) || !isFinite(y) || parts[1] === undefined || parts[2] === undefined) return { kind: 'bad', why: '/moveto x y [z]' };
      return { kind: 'host', fn, args: [Math.round(x), Math.round(y)], text };
    }
    if (fn === 'Select') { const n = parts.slice(1).join(' ').trim(); return n ? { kind: 'host', fn, args: [n], text } : { kind: 'bad', why: '/target <name>' }; }
    if (fn) return { kind: 'host', fn, args: [], text };
    if (CMD_INBOX_RUN.indexOf(w) >= 0) return { kind: 'run', text };
    return { kind: 'needs-mcp', why: `${w} needs MCP (run_account_command) - the file channel cannot do it` };
  }
  if (text[0] === '@') return { kind: 'needs-mcp', why: `${text} needs MCP (close_account / open_account)` };
  return { kind: 'bad', why: 'a command starts with ! or /' };
}
/** one poll; io = { state, me, now, exists(), mtime(), read(), ackExists(id), ack(id, obj), ready(), inParty(), teamOf(n), exec(plan, e), log(msg) } */
function cmdInboxStep(io) {
  const st = io.state;
  if (!st.seen) st.seen = {};
  if (!io.me || !io.exists()) return 0;
  let mt = null; try { mt = String(io.mtime()); } catch (e) { return 0; }
  if (mt === st.mt && !st.retry) return 0;
  let entries;
  try { entries = io.read(); } catch (e) { st.mt = null; return 0; }    // half written / locked: next second
  st.mt = mt; st.retry = false;
  const t = io.now();
  Object.keys(st.seen).forEach(id => { if (t - st.seen[id] > 600000) delete st.seen[id]; });
  const sel = cmdInboxSelect(entries, io.me, t, st.seen, io.teamOf);
  sel.expired.forEach(e => {
    st.seen[e.id] = t;
    try { if (!io.ackExists(e.id)) io.ack(e.id, { id: e.id, name: io.me, ok: false, status: 'expired', cmd: e.cmd, at: t, error: `older than ${CMD_INBOX_MAX_AGE / 1000} s - not run` }); } catch (er) { }
  });
  let ran = 0;
  for (const e of sel.run) {
    if (io.ackExists(e.id)) { st.seen[e.id] = t; continue; }               // already done (before a script reload)
    if (!io.ready()) { st.retry = true; continue; }                         // logging in / loading: try again next second
    const plan = cmdInboxPlan(e, { inParty: io.inParty() });
    st.seen[e.id] = t;
    let r;
    if (plan.kind === 'needs-mcp' || plan.kind === 'bad') r = { ok: false, error: plan.why, status: plan.kind };
    else { try { r = io.exec(plan, e) || { ok: true }; } catch (er) { r = { ok: false, error: String(er && er.message || er) }; } }
    try { io.ack(e.id, Object.assign({ id: e.id, name: io.me, cmd: e.cmd, kind: plan.kind, at: io.now(), delayMs: io.now() - Number(e.at) }, r)); } catch (er) { }
    try { io.log(`file command ${e.id} from ${e.from || '?'}: ${e.cmd} -> ${r.ok ? 'OK ' + (r.how || plan.kind) : 'FAILED ' + (r.error || '')}`); } catch (er) { }
    ran++;
  }
  return ran;
}
// CMDINBOX-END
const cmdInbox = { state: { mt: null, retry: false, seen: {} } };
const CMD_INBOX_FILE = SWARM_ROOT + '\\Logs\\cmd\\inbox.json';
const cmdAckFile = (id) => `${SWARM_ROOT}\\Logs\\cmd\\ack_${id}_${Me.Name}.json`;
function cmdInboxExec(plan) {
  switch (plan.kind) {
    case 'party': SayToParty(plan.text); return { ok: true, how: `party chat from ${Me.Name} (same as the MCP path)` };
    case 'local': setTimeout(() => { try { handleSay(Me.Name, plan.text, 3); } catch (er) { logError(`file command '${plan.text}'`, er); } }, 0); return { ok: true, how: `handleSay in ${Me.Name}'s window` };
    case 'run': {                                 // CMDFIX2-BOTPARTY-2026-10-12: /sit + /stand state-aware (L2Swarm's handler is a toggle)
      const w0 = String(plan.text).trim().toLowerCase();
      if (w0 === '/sit' || w0 === '/stand') {
        let sit = false; try { sit = !!Me.IsSitting; } catch (e) { }
        if (w0 === '/stand') { if (!sit) { rest.sitting = false; return { ok: true, how: 'already standing - nothing sent (L2Swarm /stand is a sit/stand toggle)' }; } RunCommand('/stand'); rest.sitting = false; return { ok: true, how: 'stood up' }; }
        if (sit) return { ok: true, how: 'already sitting - nothing sent (L2Swarm /sit is a sit/stand toggle)' };
        RunCommand('/sit'); return { ok: true, how: 'sat down (the script stands it up before its next walk)' };
      }
      RunCommand(plan.text); return { ok: true, how: `RunCommand('${plan.text}')` };
    }
    case 'host':
      switch (plan.fn) {
        case 'StopCombat': stopCombatG(); break;          // CMDFIX2-BOTPARTY-2026-10-12: also the script's fight flag (NNAV.wantCombat)
        case 'StartCombat': StartCombat(); break;
        case 'EnableBot': EnableBot(); break;
        case 'DisableBot': DisableBot(); break;
        case 'GoToPoint': standUp(); navUserMove(plan.args[0], plan.args[1], undefined, 'moveto'); break;   // owned + never rejects (3.8.17)
        case 'Select': { const c = Select(plan.args[0]); if (!c) return { ok: false, error: `no "${plan.args[0]}" in sight` }; break; }
        case 'AttackTarget': { const t = Target; if (!t) return { ok: false, error: 'no target' }; Attack(num(t.objId)); break; }
        case 'Loc': return { ok: true, how: 'position', result: `${Math.round(Me.X)} ${Math.round(Me.Y)} ${Math.round(Me.Z)}` };
        default: return { ok: false, error: 'unknown host call ' + plan.fn };
      }
      return { ok: true, how: plan.fn + (plan.args && plan.args.length ? '(' + plan.args.join(', ') + ')' : '()') };
  }
  return { ok: false, error: 'cannot run ' + plan.kind };
}
setInterval(() => {
  let me = ''; try { me = String(Me.Name || ''); } catch (e) { }
  cmdInboxStep({
    state: cmdInbox.state, me, now,
    exists: () => File.Exists(CMD_INBOX_FILE),
    mtime: () => String(File.GetLastWriteTimeUtc(CMD_INBOX_FILE).Ticks),
    read: () => JSON.parse(File.ReadAllText(CMD_INBOX_FILE)),
    ackExists: (id) => File.Exists(cmdAckFile(id)),
    ack: (id, obj) => File.WriteAllText(cmdAckFile(id), JSON.stringify(obj)),
    ready: () => { try { return !!IsCharacterReady(); } catch (e) { return false; } },
    inParty: () => { let n = 0; try { n = num(PartyList.Count); } catch (e) { } return n > 0; },
    teamOf, exec: cmdInboxExec, log: (m) => note(m),
  });
}, 1000);

// ---------------------------------------------------------------------------
// ORDER QUEUE (user 2026-10-13 12:20: "make sure the state machine runs as it should in the system - it is annoying that the commands we
// send keep not working"). The bot side of the durable order queue (dashboard side: Dashboard/orderqueue.js, doc in its header).
//   2026-10-13 12:09 "!dawn" to 13 parties right after the brain pool restart (12:06): only 10 characters logged "received", the other
//   leaders were not connected yet, the party-chat line was lost and the dashboard said ok. Orders were also lost during swarm.js reloads,
//   pool restarts, agent reconnects and headless relogins.
// Every dashboard '!' order is written to Logs\orders\<Name>.json for EVERY character that has to hear it (a party order: each member, with
// from = the party leader = exactly what party chat delivered before). This window polls its file once a second (time stamp only; a full
// read every 10 s and on every start) and runs each entry addressed to it EXACTLY ONCE: handleSay(from, cmd) like the party-chat path.
// Its progress goes to Logs\orders\<Name>.state.json (only this window writes it; heartbeat every 15 s):
//   delivered (read, not ready yet) -> acknowledged (written BEFORE it runs: an id in the state file never runs again, also after a reload)
//   -> running (an ORDER_CMDS order: until its retry loop / control slot ends, it fails, or a newer order replaces it) -> done | failed |
//   superseded | expired (older than its ttl when I could read it) | cancelled (dashboard Orders view).
// A new order (orderNewFor) supersedes the older ones: not-yet-run ones are skipped, the running one is marked superseded (orderBegin
