      const setDir = `${__DIR__}\\Settings\\`, abs = /^[a-z]:\\/i.test(file);
      const rel = !abs ? file : file.toLowerCase().startsWith(setDir.toLowerCase()) ? file.slice(setDir.length) : null;
      const path = rel ? setDir + rel : file;
