      const pts = [];
      try { const xml = String(File.ReadAllText(path)).split(/<\/ExternalPoly>/i)[0]; const re = /<point\s+x="(-?[\d.]+)"\s+y="(-?[\d.]+)"/gi; let m; while ((m = re.exec(xml))) pts.push({ x: +m[1], y: +m[2] }); } catch (e) { logError('zone read', e); }
