async function runRaidSequence() {
  stopCombatG();
  raidPrep.ready = {}; raidPrep.ddStartAt = 0; raidCtl.aggroAt = 0;
  Object.assign(raidSeq, { fullAt: 0, gateSaid: false, miss: {}, why: {} });
  const boss = state.bossName ? findMobByName(state.bossName, 3000) : null;
  if (state.bossName && !boss) {
    log(`Boss '${state.bossName}' not found within 3000 range!`);
    return;
  }

  await sleep(CONFIG.raidDelays[state.role] || 0);
  const myRun = raidSeq.runs = (raidSeq.runs || 0) + 1; raidSeq.running = true;   // self-defence / hit-back leave targeting to the routine
  try {
  switch (state.role) {
    case 'sk':            await raidSK(boss); break;
    case 'necromancer':   await raidDealer(boss); break;
    case 'nuker':         await raidDealer(boss); break;   // Archmage / Storm Screamer / Mystic Muse / Soultaker: strongest nukes from range (skill plan by name)   // nukes; debuffs via raidDebuffStep once the destroyers hit the boss
    case 'shilliensaint': await raidSaint(boss); break;
    case 'doomcryer':     await raidDoomcryer(); break;
    case 'inspector':     raidInspector(boss).catch(e => logError('raidInspector', e)); await raidDealer(boss); break;   // debuffs + dealing
    case 'doombringer':   await raidDealer(boss); break;
    case 'destroyer':     await raidDealer(boss); break;
    case 'bishop':
      break;                                     // the healer brain (healTick) heals in raids too
    default: {                                   // ROLE KINDS (2026-10-10): generic tokens; legacy names without a case (crafter, spoiler, dagger, healer) do nothing as before
      let rr = rkRaidRoutine(state.role);
      // RAIDDEALER-2026-10-15 (tester: "Bounty Hunter doesn't seem to be interested in killing this raid boss"): the old role names spoiler / dagger /
      // crafter had no raid routine and stood still the whole fight. They are melee fighters: they deal damage like every other dealer
      // (behind the boss, minions first with the focus, all their attack skills).
      if (!rr && /^(spoiler|dagger|crafter)$/.test(String(state.role || ''))) rr = 'dealer';
      if (rr === 'tank') await raidSK(boss);    // the SK opener generalised: aggro by skill data (tankReady), emergency by AbnormalType
      else if (rr === 'dealer') await raidDealer(boss);   // melee / melee buffer behind the boss, archer + mystic buffer + summoner from range; buffer upkeep + servitor run beside it
    }
  }
  } finally { if (raidSeq.runs === myRun) raidSeq.running = false; }
}

