// --- Destroyer i raid: angrib + AUTOMATISK re-Frenzy via mid-fight drain --
async function raidDestroyer(boss) {
  const s = SKILLS.destroyer;

  // Kom vi ind via !go har vi allerede Frenzy. Via !raid direkte: prøv nu.
  if (now() - state.frenzyLastCast > 30000) {
    if (Me.HpPercent < CONFIG.destroyerFrenzyBelow) {
      await cast(s.frenzy, 1000);
      await cast(s.zealot, 1000);
      state.frenzyLastCast = now();
    } else {
      await drainAndFrenzy(false);               // drain først, så buffs
    }
    await cast(s.rage, 1000);
  }

  if (boss && !boss.IsDead) {
    Send.Action(boss.objId);
    await sleep(300);
    Send.Attack(boss.objId);              // rene auto-attacks = max crit-dmg
  }

  // Overvågning: når Frenzy nærmer sig udløb -> drain partner -> re-Frenzy
  while (state.mode === 'raid' && boss && !boss.IsDead && state.running) {
    await sleep(2000);

    const frenzyAge = now() - state.frenzyLastCast;
    const expiringSoon = frenzyAge > CONFIG.frenzyDurationMs - CONFIG.refrenzyLeadMs;

    if (expiringSoon && !state.draining) {
      log('Frenzy expiring soon — mid-fight drain!');
      await drainAndFrenzy(true);                // drainer, re-buffer, re-engager boss
    }

    // Safety: hvis vi af en eller anden grund ikke angriber, re-engage
    if (!Me.IsInCombat && !state.draining && !boss.IsDead) {
      Send.Action(boss.objId);
      await sleep(300);
      Send.Attack(boss.objId);
    }
  }
}

// --- Bishop: differentieret heal — gulvet redder destroyers fra at dø ----
async function bishopLoop() {
  const s = SKILLS.bishop;
  const destros = destroyerNames();

  while ((state.mode === 'raid' || state.mode === 'prep') && state.running) {
    try {
      let target = null, useRestore = false;

      for (const m of partyMembersAlive()) {
        const isDestroyer = destros.includes(m.Name);
        const threshold = isDestroyer
          ? CONFIG.bishopHealDestroyerBelow      // 20% — KUN nødheal, Frenzy fredes
          : CONFIG.bishopHealOthersBelow;

        if (m.HpPercent < threshold) {
          target = m;
          useRestore = isDestroyer;              // Restore Life er %-baseret
          break;
        }
      }

      if (!target && Me.HpPercent < CONFIG.bishopHealOthersBelow) target = Me;

      if (target) {
        Send.Action(target.objId);
        await sleep(300);
        await cast(useRestore && s.restoreLife ? s.restoreLife : s.greaterHeal, 1800);
      } else {
        await sleep(700);
      }
    } catch (e) {
      console.error(e.stack);
      await sleep(1000);
    }
  }
}

// ---------------------------------------------------------------------------
// CHARACTER INDEX (user 2026-10-07: "command character X to transfer everything to character Y" — X may be any character on any account).
// At login the server sends the character list (packet 0x09: per character its name and the account login). The script reads it once,
// writes Logs/chars_<login>.json { login, names, at } (the dashboard's transfer function finds X's account there) and switches the
// packet hook off again. Packet bytes: [length lo, length hi, opcode, ...]; strings are UTF-16LE, 0-terminated.
// ---------------------------------------------------------------------------
(function captureCharacterList() {
  let done = false;
  // ONLY at character select (perf audit 2026-10-07 F5): a script (re)started while the character is already in game never sees 0x09, and
  // the hook ran JS for EVERY packet of the account for the full 3 minutes (x39 windows after each deploy/restart)
  try { if (IsCharacterReady()) return; } catch (e) { }
  try { Options.EnableJSOnIncomingPacket = true; } catch (e) { return; }
  const off = () => { try { Options.EnableJSOnIncomingPacket = false; } catch (e) { } };
  setTimeout(() => { if (!done) off(); }, 180000);                   // never leave the hook on (every packet would run JS)
  // the list (0x09) always comes BEFORE entering the world: once the character is in game it was captured or missed -> hook off at once
  const inGameWatch = setInterval(() => {
    if (done) { SCHED.clear(inGameWatch); return; }
    let r = false; try { r = !!IsCharacterReady(); } catch (e) { }
    if (r) { done = true; off(); SCHED.clear(inGameWatch); }
  }, 2000);
  globalThis.OnIncomingPacket = (p) => {
    if (done) return;
    try {
      if ((Number(p[2]) & 255) !== 0x09) return;
      done = true;
      const n = num(p.length || p.Length);
      const scan = (start) => {                                       // every printable UTF-16 string of 2+ characters from this byte alignment
        const out = []; let cur = '';
        for (let i = start; i + 1 < n; i += 2) {
          const c = (Number(p[i]) & 255) | ((Number(p[i + 1]) & 255) << 8);
          if (c >= 32 && c < 127) cur += String.fromCharCode(c);
          else { if (c === 0 && cur.length >= 2) out.push(cur); cur = ''; }
        }
        return out;
      };
      const a = scan(3), b = scan(4), good = (l) => l.filter(s => /^[A-Za-z0-9]{2,16}$/.test(s)).length;
      const strs = good(b) > good(a) ? b : a;                          // the strings sit at one alignment (H5: count, max, 1 byte, then names)
      // the list is pairs: name, login, name, login, ... (2026-10-07: "the string that repeats" swapped them on one-character accounts)
      const words = strs.filter(x => /^[A-Za-z0-9]{2,16}$/.test(x));
      const login = words[1] || '';
      const names = words.filter((x, i) => i % 2 === 0 && x !== login);
      // MERGE with what the file already knows (2026-10-07: the parser sees only one name per account, so every login wiped Constructed)
      if (login && /^[A-Za-z0-9]{3,16}$/.test(login)) { try { const old = JSON.parse(File.ReadAllText(`${SWARM_ROOT}/Logs/chars_${login.toLowerCase()}.json`)); (old.names || []).forEach(n => { if (!names.includes(n)) names.push(n); }); } catch (e) { } }
      if (login && /^[A-Za-z0-9]{3,16}$/.test(login)) File.WriteAllText(`${SWARM_ROOT}/Logs/chars_${login.toLowerCase()}.json`, JSON.stringify({ login: login.toLowerCase(), names, at: new Date().toISOString() }));
    } catch (e) { } finally { if (done) setTimeout(off, 500); }
  };
})();

