// ---------------------------------------------------------------------------
// KORT-KLIK LOGGER  —  når brugeren klikker på kortet: log koordinater + den sti L2Swarm selv går (20 s)
// (så scriptets navigation kan efterligne L2Swarms egen) -> Logs/mapclick_<navn>.log
// ---------------------------------------------------------------------------
globalThis.OnMapClick = (mapX, mapY) => {
  const f = `${SWARM_ROOT}\\Logs\\mapclick_${Me.Name}.log`;
  const t0 = now();
  const line = (m) => appendShared(f, `${new Date().toISOString()} ${m}\r\n`);
  let pathInfo = '';
  try { const p = findPathNow(new Point(Math.round(mapX), Math.round(mapY))); pathInfo = ` FindPath=${p ? p.Count : 'null'} pts`; } catch (e) { pathInfo = ` FindPath error: ${e.message}`; }
  line(`CLICK mapX=${mapX} mapY=${mapY} | I am at ${Math.round(Me.X)},${Math.round(Me.Y)},${Math.round(Me.Z)}${pathInfo} | bot=${IsEnabled} moving=${Me.IsMoving}`);
  note(`map click ${Math.round(mapX)},${Math.round(mapY)} — logging L2Swarm's path`);
  let last = { x: Me.X, y: Me.Y };
  const iv = setInterval(() => {
    const d = Math.hypot(Me.X - last.x, Me.Y - last.y);
    if (d > 30) { line(`  +${((now() - t0) / 1000).toFixed(1)}s ${Math.round(Me.X)},${Math.round(Me.Y)},${Math.round(Me.Z)} moving=${Me.IsMoving}`); last = { x: Me.X, y: Me.Y }; }
    if (now() - t0 > 20000) { SCHED.clear(iv); line(`  end: ${Math.round(Me.X)},${Math.round(Me.Y)} distance to click ${Math.round(Math.hypot(Me.X - mapX, Me.Y - mapY))}`); }
  }, 300);
};
